function inPath(q){ return state.history.some(h=>h.q===q) || state.cur.q===q; }
function isOSS(){ return (state.answers.Q4||[]).includes("A6"); }
function sectionB(){ return inPath("Q7") && !(state.answers.Q7||[]).includes("A9"); }
function gr(){ if(!inPath("Q3a")) return null; const a=state.answers.Q3a||[]; return a.includes("A1")?"public":a.includes("A2")?"private":null; }

function acc(blocks, openFirst){
  return blocks.map((b,i)=>`<details class="acc"${openFirst&&i===0?" open":""}><summary><span class="acc-title">${b.role}</span><span class="acc-ref">${b.ref}</span></summary><div class="acc-body">${b.html}</div></details>`).join("");
}
function moreSection(blocks){
  blocks = blocks.filter(Boolean);
  return blocks.length ? `<h2>Περισσότερες πληροφορίες</h2>${acc(blocks,false)}` : "";
}
function obligationsHTML(mode){
  const roles = state.answers.Q2||[];
  const has = r => roles.includes(r);
  const rightsRole = has("A7")||has("A8");
  let blocks = [], note = "";
  const tb = transparencyBlock();
  if (mode==="hr"){
    if (has("A1")||has("A5")) blocks.push(OBL_HR.A1);
    const sectionA = !inPath("Q10") && !sectionB();
    ["A5","A6","A3","A4","A2"].filter(has).forEach(r=>blocks.push(r==="A5" && !sectionA ? PM_OTHER : OBL_HR[r]));
    if (tb) blocks.push(tb);
    if (rightsRole) blocks.push(RIGHTS(true));
  } else if (isOSS()){
    if (tb) blocks.push(tb);
    if (rightsRole) blocks.push(RIGHTS(false));
    note = `<p class="small">Επειδή ισχύει η εξαίρεση ανοικτού κώδικα, εμφανίζονται μόνο οι υποχρεώσεις διαφάνειας του άρθρου 50.</p>`;
  } else {
    if (has("A1")||has("A5")) blocks.push(OBL_NOTHR.prov(mode));
    if (mode==="nothr63" && has("A6")) blocks.push(OBL_NOTHR.rep);
    if (has("A2")) blocks.push(OBL_NOTHR.dep);
    if (has("A3")||has("A4")) blocks.push(OBL_NOTHR.trade);
    if (tb) blocks.push(tb);
    if (rightsRole) blocks.push(RIGHTS(false));
  }
  // Υποχρέωση καταχώρισης στο Μητρώο για φορείς του Δημοσίου
  if (gr() === "public") {
    blocks.push({
      role: "Καταχώριση συστήματος ΤΝ στο Μητρώο του δημόσιου τομέα",
      ref: "Άρθρο 21 ν. 5321/2026",
      html: GR_REGISTRY
    });
  }
  const more = moreSection([greeceBlock(mode==="hr"?"hr":"nothr"), PENALTIES]);
  const head = `<h2>Οι υποχρεώσεις σας</h2>`;
  if (!blocks.length) return head+`<p>Ο Κανονισμός ΤΝ δεν επιβάλλει υποχρεώσεις για τον ρόλο που επιλέξατε σε αυτό το αποτέλεσμα.</p>`+more;
  return head+acc(blocks,true)+note+more;
}
