function transparencyBlock(){
  const t = state.answers.Q12||[];
  if (!inPath("Q12") || !t.length || t.includes("A6")) return null;
  const it = [];
  if (t.includes("A1")) it.push(["Πάροχος",`Σχεδιάζει το σύστημα ώστε τα πρόσωπα να ενημερώνονται ότι αλληλεπιδρούν με σύστημα ΤΝ, εκτός αν αυτό είναι προφανές για ένα εύλογα ενημερωμένο, προσεκτικό και συνετό πρόσωπο. Εξαιρούνται συστήματα που επιτρέπονται από τον νόμο για τον εντοπισμό, την πρόληψη, τη διερεύνηση ή τη δίωξη αξιόποινων πράξεων, εκτός αν είναι διαθέσιμα στο κοινό για την καταγγελία αξιόποινων πράξεων (άρθρο 50 παρ. 1).`]);
  if (t.includes("A2")) it.push(["Πάροχος",`Διασφαλίζει ότι τα στοιχεία εξόδου επισημαίνονται σε μηχαναγνώσιμο μορφότυπο και είναι ανιχνεύσιμα ως τεχνητά παραγόμενα ή αλλοιωμένα, με τεχνικές λύσεις αποτελεσματικές, διαλειτουργικές, στιβαρές και αξιόπιστες στον βαθμό που είναι τεχνικά εφικτό. Δεν ισχύει για συστήματα που επιτελούν υποβοηθητική λειτουργία τυποποιημένης επιμέλειας ή δεν αλλοιώνουν ουσιωδώς τα δεδομένα εισόδου (άρθρο 50 παρ. 2). Συστήματα που διατέθηκαν πριν από 2 Αυγούστου 2026 συμμορφώνονται έως 2 Δεκεμβρίου 2026 (άρθρο 111 παρ. 4, Κανονισμός (ΕΕ) 2026/1744).`]);
  if (t.includes("A3")) it.push(["Φορέας εφαρμογής",`Ενημερώνει τα πρόσωπα που εκτίθενται στο σύστημα αναγνώρισης συναισθημάτων ή βιομετρικής κατηγοριοποίησης για τη λειτουργία του και επεξεργάζεται τα δεδομένα σύμφωνα με τον ΓΚΠΔ, τον Κανονισμό (ΕΕ) 2018/1725 και την Οδηγία (ΕΕ) 2016/680 (άρθρο 50 παρ. 3).`]);
  if (t.includes("A4")) it.push(["Φορέας εφαρμογής",`Γνωστοποιεί ότι το περιεχόμενο εικόνας, ήχου ή βίντεο έχει παραχθεί ή αλλοιωθεί τεχνητά. Για προδήλως καλλιτεχνικό, δημιουργικό, σατιρικό ή φανταστικό έργο, αρκεί να γνωστοποιείται η ύπαρξη τέτοιου περιεχομένου χωρίς να παρεμποδίζεται η παρουσίαση ή η απόλαυση του έργου (άρθρο 50 παρ. 4).`]);
  if (t.includes("A5")) it.push(["Φορέας εφαρμογής",`Γνωστοποιεί ότι το κείμενο έχει παραχθεί ή αλλοιωθεί τεχνητά. Δεν ισχύει όταν το περιεχόμενο έχει υποβληθεί σε ανθρώπινη επανεξέταση ή συντακτικό έλεγχο και φυσικό ή νομικό πρόσωπο φέρει τη συντακτική ευθύνη της δημοσίευσης (άρθρο 50 παρ. 4).`]);
  return {role:"Υποχρεώσεις διαφάνειας",ref:"Άρθρο 50",html:`<dl class="who-list">${it.map(([w,x])=>`<div><dt>${w}</dt><dd>${x}</dd></div>`).join("")}</dl>
<p class="small">Οι πληροφορίες παρέχονται με σαφή και διακριτό τρόπο το αργότερο κατά την πρώτη αλληλεπίδραση ή έκθεση και τηρούν τις απαιτήσεις προσβασιμότητας (άρθρο 50 παρ. 5). Σε επίπεδο Ένωσης ενθαρρύνονται κώδικες πρακτικής για την επισήμανση περιεχομένου που παράγεται με ΤΝ (άρθρο 50 παρ. 7).</p>`};
}

